"use client";

import { usePathname } from "next/navigation";
import Link from "next/link";
import styles from "./dashboard.module.css";
import React, { useState, useEffect } from "react";
import { ThemeToggle } from "@/components/ThemeToggle";
import { createClient } from "@/lib/supabase";

// Icons (Simple SVGs for now to adhere to Vanilla request, 
// usually we'd use lucide-react but I'll embed to avoid dep issues for now 
// or I can install lucide-react if preferred. I'll use text emojis/simple svgs for speed)

const MENU_ITEMS = [
    { name: "Dashboard", href: "/dashboard", icon: "📊" },
    { name: "Opportunities", href: "/dashboard/opportunities", icon: "🌍" },
    { name: "Visa & Checklist", href: "/dashboard/visa", icon: "📝" },
    { name: "Documents", href: "/dashboard/documents", icon: "📂" },
    { name: "Budget", href: "/dashboard/budget", icon: "💰" },
    { name: "Calendar", href: "/dashboard/calendar", icon: "📅" },
    { name: "Travel Passport", href: "/dashboard/passport", icon: "🏕️" },
    { name: "Forum", href: "/dashboard/forum", icon: "💬" },
    { name: "Settings", href: "/dashboard/settings", icon: "⚙️" },
];

export default function DashboardLayout({
    children,
}: {
    children: React.ReactNode;
}) {
    const pathname = usePathname();
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);
    const [showNotifications, setShowNotifications] = useState(false);

    return (
        <div className={styles.layout}>
            {/* Sidebar */}
            <aside className={`${styles.sidebar} ${isSidebarOpen ? styles.sidebarOpen : ''}`}>
                <div className={styles.sidebarHeader}>
                    <Link href="/dashboard" className={styles.brand} style={{ textDecoration: 'none', color: 'inherit' }}>
                        ErasmusHub
                    </Link>
                </div>

                <nav className={styles.nav}>
                    {MENU_ITEMS.map((item) => {
                        const isActive = pathname === item.href;
                        return (
                            <Link
                                key={item.href}
                                href={item.href}
                                className={`${styles.navItem} ${isActive ? styles.navItemActive : ''}`}
                                onClick={() => setIsSidebarOpen(false)}
                            >
                                <span style={{ fontSize: '1.2rem' }}>{item.icon}</span>
                                {item.name}
                            </Link>
                        );
                    })}
                </nav>

                <div className={styles.userProfile}>
                    <div className={styles.avatar} style={{ backgroundColor: 'var(--primary)' }}>S</div>
                    <div className={styles.userInfo}>
                        <span className={styles.userName}>Student</span>
                        <span className={styles.userPlan}>Free Plan</span>
                    </div>
                </div>
            </aside>

            {/* Main Content */}
            <div className={styles.main}>
                <header className={styles.topbar}>
                    <h2 className={styles.pageTitle}>
                        {MENU_ITEMS.find(i => i.href === pathname)?.name || "Dashboard"}
                    </h2>
                    <div className={styles.topbarActions} style={{ position: 'relative' }}>
                        <ThemeToggle />

                        {/* Notify Btn */}
                        <button
                            className={styles.actionBtn}
                            title="Notifications"
                            onClick={() => setShowNotifications(!showNotifications)}
                        >
                            🔔
                            {/* Red Dot if unread */}
                            <span style={{
                                position: 'absolute', top: '5px', right: '5px',
                                width: '8px', height: '8px', backgroundColor: 'red', borderRadius: '50%'
                            }}></span>
                        </button>

                        {/* Dropdown */}
                        {showNotifications && (
                            <div style={{
                                position: 'absolute',
                                top: '100%',
                                right: '0',
                                marginTop: '0.5rem',
                                width: '280px',
                                backgroundColor: 'var(--background)',
                                border: '1px solid var(--border)',
                                borderRadius: '0.75rem',
                                boxShadow: '0 4px 20px rgba(0,0,0,0.15)',
                                zIndex: 100,
                                padding: '1rem',
                                animation: 'fadeIn 0.2s ease'
                            }}>
                                <h4 style={{ margin: '0 0 0.75rem 0', fontSize: '0.9rem', color: 'var(--secondary-foreground)' }}>Notifications</h4>
                                <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                                    <div style={{ fontSize: '0.85rem', paddingBottom: '0.5rem', borderBottom: '1px solid var(--border)' }}>
                                        <p style={{ margin: 0, fontWeight: 500 }}>Welcome to ErasmusHub! 🎉</p>
                                        <span style={{ fontSize: '0.75rem', color: 'var(--secondary-foreground)' }}>Just now</span>
                                    </div>
                                    <div style={{ fontSize: '0.85rem' }}>
                                        <p style={{ margin: 0, fontWeight: 500 }}>Don't forget to set your budget.</p>
                                        <span style={{ fontSize: '0.75rem', color: 'var(--secondary-foreground)' }}>2 hours ago</span>
                                    </div>
                                    <div style={{ textAlign: 'center', marginTop: '0.5rem' }}>
                                        <small style={{ color: 'var(--primary)', cursor: 'pointer' }}>Mark all as read</small>
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* Mobile Menu Toggle */}
                        <button
                            className={styles.actionBtn}
                            style={{ display: 'md:none' }}
                            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
                        >
                            ☰
                        </button>
                    </div>
                </header>

                <main className={styles.content}>
                    {children}
                </main>
            </div>
        </div>
    );
}
